PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS vendor_settings (id INTEGER PRIMARY KEY CHECK(id=1),minimum_rating REAL NOT NULL DEFAULT 4 CHECK(minimum_rating BETWEEN 1 AND 5),annual_contribution INTEGER NOT NULL DEFAULT 200 CHECK(annual_contribution>0),renewal_months INTEGER NOT NULL DEFAULT 12 CHECK(renewal_months BETWEEN 1 AND 120),renewal_notice_days INTEGER NOT NULL DEFAULT 30 CHECK(renewal_notice_days>=0));
INSERT OR IGNORE INTO vendor_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS directory_agents(id TEXT PRIMARY KEY,name TEXT NOT NULL,company TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('agent','admin')),sample INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS directory_sessions(token_hash TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES directory_agents(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS service_areas(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL,requires_detail INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS charities(id TEXT PRIMARY KEY,name TEXT NOT NULL,logo TEXT,website TEXT,active INTEGER NOT NULL DEFAULT 1,sample INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vendors(id TEXT PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT UNIQUE NOT NULL,initials TEXT NOT NULL,logo TEXT,tone TEXT NOT NULL,description TEXT NOT NULL,services_json TEXT NOT NULL,website TEXT NOT NULL,source_url TEXT NOT NULL,source_checked_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('recommended','under_review','approved_for_invitation','invited','onboarding','contribution_pending','active','renewal_due','expired','suspended','declined','archived')),status_reason TEXT,referring_agent_id TEXT NOT NULL REFERENCES directory_agents(id),approved_at TEXT,invited_at TEXT,onboarded_at TEXT,member_since TEXT NOT NULL,sample INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vendor_contacts(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),name TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',social_url TEXT);
CREATE TABLE IF NOT EXISTS vendor_categories(vendor_id TEXT NOT NULL REFERENCES vendors(id),category_id TEXT NOT NULL REFERENCES categories(id),PRIMARY KEY(vendor_id,category_id));
CREATE TABLE IF NOT EXISTS vendor_service_areas(vendor_id TEXT NOT NULL REFERENCES vendors(id),area_id TEXT NOT NULL REFERENCES service_areas(id),detail TEXT NOT NULL DEFAULT '',PRIMARY KEY(vendor_id,area_id));
CREATE TABLE IF NOT EXISTS vendor_recommendations(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES directory_agents(id),company_name TEXT NOT NULL,normalized_name TEXT NOT NULL,contact_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,website TEXT NOT NULL,experience TEXT NOT NULL,reason TEXT NOT NULL,notes TEXT NOT NULL,submitted_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','under_review','approved_for_invitation','invited','declined','duplicate')),linked_vendor_id TEXT REFERENCES vendors(id),UNIQUE(agent_id,normalized_name));
CREATE TABLE IF NOT EXISTS recommendation_categories(recommendation_id TEXT NOT NULL REFERENCES vendor_recommendations(id),category_id TEXT NOT NULL REFERENCES categories(id),PRIMARY KEY(recommendation_id,category_id));
CREATE TABLE IF NOT EXISTS recommendation_service_areas(recommendation_id TEXT NOT NULL REFERENCES vendor_recommendations(id),area_id TEXT NOT NULL REFERENCES service_areas(id),detail TEXT NOT NULL DEFAULT '',PRIMARY KEY(recommendation_id,area_id));
CREATE TABLE IF NOT EXISTS vendor_invitations(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),recommendation_id TEXT REFERENCES vendor_recommendations(id),token_hash TEXT UNIQUE NOT NULL,recipient_email TEXT NOT NULL,invited_by TEXT NOT NULL REFERENCES directory_agents(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,accepted_at TEXT,revoked_at TEXT,sent_at TEXT);
CREATE TABLE IF NOT EXISTS vendor_reviews(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES directory_agents(id),vendor_id TEXT NOT NULL REFERENCES vendors(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),experience_type TEXT NOT NULL CHECK(experience_type IN ('agent','client')),comment TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sample INTEGER NOT NULL DEFAULT 1,UNIQUE(agent_id,vendor_id));
CREATE TABLE IF NOT EXISTS vendor_review_history(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES vendor_reviews(id),rating INTEGER NOT NULL,experience_type TEXT NOT NULL,comment TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vendor_contributions(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),charity_id TEXT NOT NULL REFERENCES charities(id),amount INTEGER NOT NULL CHECK(amount>0),contribution_date TEXT NOT NULL,renewal_date TEXT NOT NULL CHECK(renewal_date>contribution_date),verification_status TEXT NOT NULL CHECK(verification_status IN ('pending','verified','rejected')),verified_by TEXT REFERENCES directory_agents(id),reference TEXT,sample INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vendor_status_history(id INTEGER PRIMARY KEY AUTOINCREMENT,vendor_id TEXT NOT NULL REFERENCES vendors(id),old_status TEXT,new_status TEXT NOT NULL,reason TEXT NOT NULL,actor_id TEXT REFERENCES directory_agents(id),recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_outbox(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,entity_id TEXT NOT NULL,recipient TEXT NOT NULL,subject TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'awaiting_provider' CHECK(status IN ('awaiting_provider','queued','sending','sent','failed')),attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,sent_at TEXT,last_error TEXT,UNIQUE(event_type,entity_id));
CREATE INDEX IF NOT EXISTS review_vendor_idx ON vendor_reviews(vendor_id);
CREATE INDEX IF NOT EXISTS contribution_vendor_idx ON vendor_contributions(vendor_id,renewal_date);
CREATE INDEX IF NOT EXISTS recommendation_status_idx ON vendor_recommendations(status,submitted_at);
CREATE TRIGGER IF NOT EXISTS audit_vendor_status AFTER UPDATE OF status ON vendors WHEN OLD.status<>NEW.status BEGIN INSERT INTO vendor_status_history(vendor_id,old_status,new_status,reason) VALUES(NEW.id,OLD.status,NEW.status,COALESCE(NEW.status_reason,'Status changed')); END;
CREATE TRIGGER IF NOT EXISTS enforce_rating_insert AFTER INSERT ON vendor_reviews WHEN (SELECT avg(rating) FROM vendor_reviews WHERE vendor_id=NEW.vendor_id)<(SELECT minimum_rating FROM vendor_settings WHERE id=1) BEGIN UPDATE vendors SET status='suspended',status_reason='BlueBase rating below configured minimum' WHERE id=NEW.vendor_id AND status IN ('active','renewal_due'); END;
CREATE TRIGGER IF NOT EXISTS enforce_rating_update AFTER UPDATE ON vendor_reviews WHEN (SELECT avg(rating) FROM vendor_reviews WHERE vendor_id=NEW.vendor_id)<(SELECT minimum_rating FROM vendor_settings WHERE id=1) BEGIN UPDATE vendors SET status='suspended',status_reason='BlueBase rating below configured minimum' WHERE id=NEW.vendor_id AND status IN ('active','renewal_due'); END;
CREATE TRIGGER IF NOT EXISTS enforce_setting_rating AFTER UPDATE OF minimum_rating ON vendor_settings BEGIN UPDATE vendors SET status='suspended',status_reason='BlueBase rating below configured minimum' WHERE status IN ('active','renewal_due') AND (SELECT avg(rating) FROM vendor_reviews WHERE vendor_id=vendors.id)<NEW.minimum_rating; END;
CREATE TRIGGER IF NOT EXISTS audit_review_update BEFORE UPDATE ON vendor_reviews BEGIN INSERT INTO vendor_review_history(id,review_id,rating,experience_type,comment,recorded_at) VALUES(lower(hex(randomblob(16))),OLD.id,OLD.rating,OLD.experience_type,OLD.comment,OLD.updated_at); END;
PRAGMA user_version=1;
